#!/bin/sh
# Generated by forge. Notification: terminal notification through OSC 777
# (OSC 9 for iTerm.app and WezTerm).
# this script's directory, absolute (builtins)
case $0 in */*) dir=${0%/*} ;; *) dir=. ;; esac
case $dir in /*) ;; *) dir=$PWD/$dir ;; esac
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
msg=$(json_get message | tr -d '\000-\037\177' | cut -c 1-200)
[ -n "$msg" ] || msg="Claude Code needs your attention"
msg=$(printf '%s' "$msg" | json_escape)
case ${TERM_PROGRAM:-} in
  iTerm.app|WezTerm) printf '{"terminalSequence":"\\u001b]9;%s\\u0007"}\n' "$msg" ;;
  *) printf '{"terminalSequence":"\\u001b]777;notify;Claude Code;%s\\u0007"}\n' "$msg" ;;
esac
exit 0
